    [task setLaunchPath:@"/usr/bin/pgrep"];
    [task setArguments:@[@"-f", @"Simulator"]];

    NSPipe *pipe = [NSPipe pipe];
    [task setStandardOutput:pipe];
    [task launch];
    [task waitUntilExit];

    NSData *data = [[pipe fileHandleForReading] readDataToEndOfFile];
    NSString *output = [[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];
    NSArray *pids = [output componentsSeparatedByString:@"\n"];

    for (NSString *pidStr in pids) {
        if ([pidStr length] > 0) {
            pid_t simPID = (pid_t)[pidStr integerValue];
            NSLog(@"Found Simulator PID: %d", simPID);

            // Try to get the AX application
            AXUIElementRef appRef = AXUIElementCreateApplication(simPID);
            if (appRef) {
                NSLog(@"Got AX application reference for PID %d", simPID);

                // Try to find all windows
                CFArrayRef windows;
                AXError error = AXUIElementCopyAttributeValue(appRef, kAXWindowsAttribute, (CFTypeRef *)&windows);
                if (error == kAXErrorSuccess && windows) {
                    NSLog(@"Found %ld windows", CFArrayGetCount(windows));

                    // Try to find the dialog button
                    for (CFIndex i = 0; i < CFArrayGetCount(windows); i++) {
                        AXUIElementRef window = (AXUIElementRef)CFArrayGetValueAtIndex(windows, i);

                        // Try to find the Open button
                        CFArrayRef children;
                        error = AXUIElementCopyAttributeValue(window, kAXChildrenAttribute, (CFTypeRef *)&children);
                        if (error == kAXErrorSuccess && children) {
                            [(__bridge NSArray *)children enumerateObjectsUsingBlock:^(id obj, NSUInteger idx, BOOL *stop) {
                                AXUIElementRef elem = (__bridge AXUIElementRef)obj;
                                CFStringRef title;
                                AXUIElementCopyAttributeValue(elem, kAXTitleAttribute, (CFTypeRef *)&title);
                                if (title && CFStringFind(title, CFSTR("Open"), 0).location != kCFNotFound) {
                                    NSLog(@"Found element with 'Open' in title!");
                                    // Try to click it
                                    AXUIElementPerformAction(elem, kAXPressAction);
                                    NSLog(@"Attempted to click Open button");
                                }
                                if (title) CFRelease(title);
                            }];
                            CFRelease(children);
                        }
                    }
                    CFRelease(windows);
                }
                CFRelease(appRef);
            }
        }
    }

    return 0;
}
EOF

